// LinkedIn je Person (Stefan 17.10.2026): Anfrage lesen. Sitzung aus dem Cookie wie bei ALLY 8.
// start = Link „Mit LinkedIn verbinden“ (mit ?seite=1: Unternehmensseite), rueckkehr = LinkedIn leitet zurück, einstellen = Formulare auf der Seite Marketing (Herkunft prüfen wie bei ALLY 11).
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {}, q = $json.query || {}, b = $json.body || {};
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
let art = 'einstellen', aktion = '', daten = '{}', state = '', code = '', fehler = '', ziel_art = 'profil';
if ($('Verbinden').isExecuted) { art = 'start'; ziel_art = s(q.seite) === '1' ? 'seite' : 'profil'; }
else if ($('Rückkehr').isExecuted) {
  art = 'rueckkehr'; state = s(q.state); code = s(q.code).slice(0, 2000);
  const e = s(q.error);
  // Nur feste Texte, nie error_description aus dem Link: sonst ließe sich über einen Link jede Meldung setzen.
  // Übernommen wird der Text nur bei gültigem state (siehe Daten bauen) (Stefan 17.10.2026)
  if (e) fehler = ['user_cancelled_login', 'user_cancelled_authorize'].includes(e) ? 'Anmeldung bei LinkedIn abgebrochen.' : 'LinkedIn hat die Anmeldung abgelehnt.';
} else {
  const herkunft = String(h.origin || ''), verweis = String(h.referer || '');
  // Verweis nur mit Trennzeichen nach dem Seitenpfad (Ende, '/', '?' oder '#'), sonst gälte auch /webhook/web-xyz (Stefan 17.10.2026)
  const SEITE_PFAD = HOST + '/webhook/web';
  const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
  const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
  aktion = herkunftOk && ['linkedin_app', 'linkedin_trennen', 'linkedin_seite_app', 'linkedin_seite_trennen'].includes(s(b.aktion)) ? s(b.aktion) : 'ungueltig';
  daten = JSON.stringify({ client_id: s(b.client_id), client_secret: s(b.client_secret) });
}
return [{ json: { art, token, aktion, daten, state, code, fehler, ziel_art, basis: HOST } }];

// Ergebnis der Anmeldung bei LinkedIn für „Speichern“: persönliches Profil oder Unternehmensseite (Schlüssel geht nur in die Datenbank; dieser Ablauf speichert keine Ausführungsdaten)
const A = $('Anfrage lesen').first().json;
const R = $('Datenbank').first().json.r || {};
const art = R.art === 'seite' ? 'seite' : 'profil';
let d = {};
if ($('Schlüssel holen').isExecuted) {
  const t = $('Schlüssel holen').first().json || {}, tb = t.body || {};
  if (Number(t.statusCode) !== 200 || !tb.access_token) d.fehler = 'LinkedIn hat die Anmeldung nicht bestätigt' + (tb.error_description ? ': ' + String(tb.error_description).slice(0, 150) : '');
  else if (art === 'seite') {
    // Unternehmensseiten, bei denen die Person Administrator ist; bei mehreren die mit dem Namen des eigenen Unternehmens, sonst die erste
    const acl = $('Seiten holen').isExecuted ? ($('Seiten holen').first().json || {}) : {};
    const lk = $('Seitennamen holen').isExecuted ? ($('Seitennamen holen').first().json || {}) : {};
    const ids = ((acl.body || {}).elements || []).map(e => String(e.organization || e.organizationTarget || '').split(':').pop()).filter(x => /^[0-9]{1,20}$/.test(x));
    const res = (lk.body || {}).results || {};
    const name = id => String(((res[id] || {}).localizedName) || '');
    const firma = String(R.firma || '').trim().toLowerCase();
    if (Number(acl.statusCode) !== 200) d.fehler = 'LinkedIn gibt die Unternehmensseiten nicht heraus (Status ' + (acl.statusCode || 'keine Antwort') + '). Ist der Antrag für die App schon freigegeben?';
    else if (!ids.length) d.fehler = 'Du bist bei keiner Unternehmensseite als Administrator eingetragen';
    else {
      const id = ids.find(i => firma && name(i).trim().toLowerCase() === firma) || ids[0];
      d = { art, token: String(tb.access_token), expires_in: Number(tb.expires_in) || 0, org: id, name: name(id).slice(0, 200) };
    }
  } else {
    const p = $('Profil holen').isExecuted ? ($('Profil holen').first().json || {}) : {}, pb = p.body || {};
    if (Number(p.statusCode) !== 200 || !pb.sub) d.fehler = 'Profil nicht lesbar. Die App braucht das Produkt „Sign In with LinkedIn using OpenID Connect“';
    else d = { art, token: String(tb.access_token), expires_in: Number(tb.expires_in) || 0, sub: String(pb.sub),
      name: String(pb.name || [pb.given_name, pb.family_name].filter(Boolean).join(' ')).slice(0, 200) };
  }
} else {
  // Meldung von LinkedIn nur übernehmen, wenn der state gültig war (linkedin_zurueck ok); sonst fester Text (Stefan 17.10.2026)
  d.fehler = R.ok === true ? (A.fehler || 'keine Rückmeldung von LinkedIn') : 'Die Rückkehr von LinkedIn war ungültig oder abgelaufen. Bitte noch einmal verbinden.';
}
return [{ json: { token: A.token, daten: JSON.stringify(d), art } }];

// Weiterleitung: zu LinkedIn (Verbinden) oder zurück auf die Seite Marketing; Sitzung wie bei ALLY 8 behandeln
const HOST = $('Anfrage lesen').first().json.basis || '', SEITE = '/webhook/web';
const A = $('Anfrage lesen').first().json;
const r = ($('Speichern').isExecuted ? $('Speichern').first().json.r : $('Datenbank').first().json.r) || {};
// Stelle auf der Seite (Stefan 17.10.2026): wie bei ALLY 11, damit die Seite nach dem Speichern nicht nach oben springt
const ZQ = A.art === 'einstellen' ? ($('Einstellen').first().json.query || {}) : {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
// BA10 Teil 4 (Stefan 21.10.2026): Rücksprung zur aufrufenden Oberfläche. ui = Ziel aus der Anfrage (Start: von=app, gesetzt von ALLY 20) bzw. aus dem
// Cookie ally_li_ziel (Rückkehr), nur Werte aus der Liste erlaubter interner Ziele; ohne ui wie bisher die Seite Marketing hier. Je Antwort geht nur ein Set-Cookie:
// beim Start aus der neuen Oberfläche das Ziel-Cookie (15 Minuten), bei der Rückkehr bzw. einem Start von hier mit altem Ziel-Cookie dessen Löschung
// (die Sitzung hat ALLY 20 kurz vorher für 30 Tage gesetzt). Ablauf und Datenbank sonst unverändert.
// Stufe 2a (23.10.2026): neu = neue Web-App, Einstellungen › Verbindungen (Pfad /neu der eigenen Adresse der Oberfläche)
const ZIEL_UI = { app: '/webhook/app?seite=einstellungen&bereich=marketing#a-veroeffentlichen', neu: '/neu?seite=einstellungen&bereich=verbindungen' };
const erlaubt = v => Object.prototype.hasOwnProperty.call(ZIEL_UI, v);
const W0 = A.art === 'start' ? $('Verbinden').first().json : A.art === 'rueckkehr' ? $('Rückkehr').first().json : {};
const zk = (String(((W0 || {}).headers || {}).cookie || '').split(';').map(x => x.trim()).find(x => x.startsWith('ally_li_ziel=')) || '').slice('ally_li_ziel='.length);
const von = String(((W0 || {}).query || {}).von ?? '').trim();
const ui = A.art === 'start' ? (erlaubt(von) ? von : '') : A.art === 'rueckkehr' && erlaubt(zk) ? zk : '';
const zkeks = (wert, alter) => 'ally_li_ziel=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=Lax';
let ziel, cookie = '';
if (r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = ui ? '/webhook/app?m=abgelaufen' : SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else {
  if (A.art === 'start' && r.ok) ziel = 'https://www.linkedin.com/oauth/v2/authorization?response_type=code&client_id=' + encodeURIComponent(r.client_id)
    + '&redirect_uri=' + encodeURIComponent(HOST + String($('Datenbank').first().json.aussen || '') + '/linkedin') + '&state=' + encodeURIComponent(r.state) + '&scope=' + encodeURIComponent(r.scope || 'openid profile w_member_social');
  else ziel = ui ? ZIEL_UI[ui] : A.art === 'einstellen' ? stelle(SEITE + '?ansicht=marketing') : SEITE + '?ansicht=marketing';
  if (A.token) cookie = keks(A.token, 2592000);
  if (A.art === 'start' && r.ok && ui) cookie = zkeks(ui, 900);
  else if ((A.art === 'start' || A.art === 'rueckkehr') && erlaubt(zk)) cookie = zkeks('', 0);
}
return [{ json: { ziel, set_cookie: cookie } }];
